                            ],
                            "properties": {
                              "cardNumber": { "type": "string" },
                              "cardNumberLast4": { "type": "string" },
                              "productName": { "type": "string" },
                              "statementDate": { "$ref": "#/components/schemas/IssuedDate" },
                              "lastPayDate": { "$ref": "#/components/schemas/IssuedDate" },
                              "nextStatementDate": { "$ref": "#/components/schemas/Date" },
                              "nextLastPayDate": { "$ref": "#/components/schemas/Date" },
                              "debtTL": { "$ref": "#/components/schemas/CurrencyBlock" },
                              "debtUSD": { "$ref": "#/components/schemas/CurrencyBlock" },
                              "debtEUR": { "$ref": "#/components/schemas/CurrencyBlock" },
                              "debtGBP": { "$ref": "#/components/schemas/CurrencyBlock" },
                              "statementPaymentStatus": { "$ref": "#/components/schemas/DebtStatus" },
                              "totalDebtPaymentStatus": { "$ref": "#/components/schemas/DebtStatus" },
                              "automaticPaymentFlag": { "type": "string", "enum": ["Y", "N"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": { "$ref": "#/components/responses/InvalidArguments" },
            "401": { "$ref": "#/components/responses/GatewayUnauthorized" },
            "404": {
              "description": "Card not found: FB_IVR_CHANNEL_120, WARNING. Example message text is not fixed.",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/ErrorEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "result": {
                            "type": "object",
                            "properties": {
                              "returnCode": { "type": "string", "enum": ["FB_IVR_CHANNEL_120"] },
                              "code": { "type": "string", "enum": ["FB_IVR_CHANNEL_120"] },
                              "type": { "type": "string", "enum": ["WARNING"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "500": { "$ref": "#/components/responses/TechnicalError" }
          }
        }
      },
      "/voice/v1/statement.week.get": {
        "post": {
          "operationId": "statement.week.get",
          "description": "Returns the current statement week and day. relationType is empty for an independent statement, M for the main card or C for the linked card. Related card fields are empty strings when there is no shared statement. Changing either card moves the shared statement. No eligibility or yearly-change-right field is defined.",
          "x-business-success": {
            "path": "result.returnCode",
            "operand": "1"
          },
          "requestBody": { "$ref": "#/components/requestBodies/CardRequest" },
          "responses": {
            "200": {
              "description": "Success: result.returnCode equals \"1\".",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/SuccessEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "data": {
                            "type": "object",
                            "required": [
                              "cardNumber", "cardNumberLast4", "productName",
                              "statementWeek", "statementDay", "statementDate",
                              "lastPayDate", "nextStatementDate", "nextLastPayDate",
                              "relationType", "relatedCardNumber", "relatedCardProductName"
                            ],
                            "properties": {
                              "cardNumber": { "type": "string" },
                              "cardNumberLast4": { "type": "string" },
                              "productName": { "type": "string" },
                              "statementWeek": { "type": "number", "enum": [1, 2, 3, 4] },
                              "statementDay": { "type": "number", "description": "Day of the month." },
                              "statementDate": { "$ref": "#/components/schemas/IssuedDate" },
                              "lastPayDate": { "$ref": "#/components/schemas/IssuedDate" },
                              "nextStatementDate": { "$ref": "#/components/schemas/Date" },
                              "nextLastPayDate": { "$ref": "#/components/schemas/Date" },
                              "relationType": { "type": "string", "enum": ["", "M", "C"] },
                              "relatedCardNumber": { "type": "string" },
                              "relatedCardProductName": { "type": "string" }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": { "$ref": "#/components/responses/InvalidArguments" },
            "401": { "$ref": "#/components/responses/GatewayUnauthorized" },
            "404": {
              "description": "Card not found: FB_IVR_CHANNEL_121, WARNING.",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/ErrorEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "result": {
                            "type": "object",
                            "properties": {
                              "returnCode": { "type": "string", "enum": ["FB_IVR_CHANNEL_121"] },
                              "code": { "type": "string", "enum": ["FB_IVR_CHANNEL_121"] },
                              "type": { "type": "string", "enum": ["WARNING"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "500": { "$ref": "#/components/responses/TechnicalError" }
          }
        }
      },
      "/voice/v1/statement.week.decide": {
        "post": {
          "operationId": "statement.week.decide",
          "description": "Preview only; does not change the card. Send the current statementDay from statement.week.get. Calling for the current week returns an error. Successful data.responseCode is 0. Dates describe the first statement and due date under the requested week.",
