      "title": "Freya Bank statement and debt HTTP contract",
      "version": "2026-10-01",
      "description": "Authority: the 2026-10-01 service contract, sections 1–6. Scope: its seven services in the test environment. All services use POST with UTF-8 JSON. Paths combine the declared /voice/v1/ base pathname with the service names. Token acquisition is not required in test: token, headers and call metadata are not checked. Production uses a bearer token obtained at POST /oauth2/token with client credentials and scope voice.statement; no credentials are supplied here. Deployment and platform examples do not define bank endpoints. Test fixtures determine exact customer-specific bodies and HTTP statuses. Missing fixture entries use the service's documented 404, or 400 INVALID_ARGUMENTS_ERROR where no 404 is defined. Client timeout, retry policy and rate limits are not specified."
    },
    "servers": [
      {
        "url": "https://core-freya-final.hamitarsln09.workers.dev"
      }
    ],
    "paths": {
      "/voice/v1/cards.list": {
        "post": {
          "operationId": "cards.list",
          "description": "Lists active cards for data.customerNo. aiFlow is CardOps in production but is ignored in test. Test cardNumber values show the first six and last four digits. Send returned cardNumber values unchanged to other services. Product names are free text and may be empty; last four digits need not be unique.",
          "x-business-success": {
            "path": "result.returnCode",
            "operand": "1"
          },
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "allOf": [
                    { "$ref": "#/components/schemas/RequestEnvelope" },
                    {
                      "type": "object",
                      "properties": {
                        "data": {
                          "type": "object",
                          "required": ["customerNo"],
                          "properties": {
                            "customerNo": { "$ref": "#/components/schemas/CustomerNo" },
                            "aiFlow": {
                              "type": "string",
                              "description": "CardOps for this use case; ignored and not required in test."
                            }
                          }
                        }
                      }
                    }
                  ]
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Success: result.returnCode equals \"1\".",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/SuccessEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "data": {
                            "type": "object",
                            "required": ["cards", "validCardsCount", "exitState"],
                            "properties": {
                              "cards": {
                                "type": "array",
                                "items": { "$ref": "#/components/schemas/Card" }
                              },
                              "validCardsCount": { "type": "number" },
                              "exitState": {
                                "type": "string",
                                "enum": ["1_CARD", "MULTI_CARD"]
                              }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": { "$ref": "#/components/responses/InvalidArguments" },
            "401": { "$ref": "#/components/responses/GatewayUnauthorized" },
            "404": {
              "description": "No valid card: FB_IVR_CHANNEL_102, WARNING. Message: Müşteriye ait geçerli kart bilgisi bulunamadı.",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/ErrorEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "result": {
                            "type": "object",
                            "properties": {
                              "returnCode": { "type": "string", "enum": ["FB_IVR_CHANNEL_102"] },
                              "code": { "type": "string", "enum": ["FB_IVR_CHANNEL_102"] },
                              "type": { "type": "string", "enum": ["WARNING"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "500": { "$ref": "#/components/responses/TechnicalError" }
          }
        }
      },
      "/voice/v1/cards.balance": {
        "post": {
          "operationId": "cards.balance",
          "description": "Called with the exact cardNumber returned by cards.list. Returns debt numbers without rounding. Currency blocks may be absent or exactly empty objects; populated blocks retain their full typed model. Missing or empty currency blocks do not mean zero debt. Response cardNumber uses first-four/last-four masking. Issued statementDate and lastPayDate may be empty for a new card. One test response is delayed by 12 seconds; delaySeconds is fixture metadata, not a response property.",
          "x-business-success": {
            "path": "result.returnCode",
            "operand": "1"
          },
          "requestBody": { "$ref": "#/components/requestBodies/CardRequest" },
          "responses": {
            "200": {
              "description": "Success: result.returnCode equals \"1\".",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/SuccessEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "data": {
                            "type": "object",
                            "required": [
                              "cardNumber", "cardNumberLast4", "productName",
                              "statementDate", "lastPayDate", "nextStatementDate",
                              "nextLastPayDate", "statementPaymentStatus",
                              "totalDebtPaymentStatus", "automaticPaymentFlag"
                            ],
                            "properties": {
                              "cardNumber": { "type": "string" },
                              "cardNumberLast4": { "type": "string" },
                              "productName": { "type": "string" },
                              "statementDate": { "$ref": "#/components/schemas/IssuedDate" },
                              "lastPayDate": { "$ref": "#/components/schemas/IssuedDate" },
                              "nextStatementDate": { "$ref": "#/components/schemas/Date" },
                              "nextLastPayDate": { "$ref": "#/components/schemas/Date" },
                              "debtTL": { "$ref": "#/components/schemas/CurrencyBlock" },
                              "debtUSD": { "$ref": "#/components/schemas/CurrencyBlock" },
                              "debtEUR": { "$ref": "#/components/schemas/CurrencyBlock" },
                              "debtGBP": { "$ref": "#/components/schemas/CurrencyBlock" },
                              "statementPaymentStatus": { "$ref": "#/components/schemas/DebtStatus" },
                              "totalDebtPaymentStatus": { "$ref": "#/components/schemas/DebtStatus" },
                              "automaticPaymentFlag": { "type": "string", "enum": ["Y", "N"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": { "$ref": "#/components/responses/InvalidArguments" },
            "401": { "$ref": "#/components/responses/GatewayUnauthorized" },
            "404": {
              "description": "Card not found: FB_IVR_CHANNEL_120, WARNING. Example message text is not fixed.",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/ErrorEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "result": {
                            "type": "object",
                            "properties": {
                              "returnCode": { "type": "string", "enum": ["FB_IVR_CHANNEL_120"] },
                              "code": { "type": "string", "enum": ["FB_IVR_CHANNEL_120"] },
                              "type": { "type": "string", "enum": ["WARNING"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "500": { "$ref": "#/components/responses/TechnicalError" }
          }
        }
      },
      "/voice/v1/statement.week.get": {
        "post": {
          "operationId": "statement.week.get",
          "description": "Returns the current statement week and day. relationType is empty for an independent statement, M for the main card or C for the linked card. Related card fields are empty strings when there is no shared statement. Changing either card moves the shared statement. No eligibility or yearly-change-right field is defined.",
          "x-business-success": {
            "path": "result.returnCode",
            "operand": "1"
          },
          "requestBody": { "$ref": "#/components/requestBodies/CardRequest" },
          "responses": {
            "200": {
              "description": "Success: result.returnCode equals \"1\".",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/SuccessEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "data": {
                            "type": "object",
                            "required": [
                              "cardNumber", "cardNumberLast4", "productName",
                              "statementWeek", "statementDay", "statementDate",
                              "lastPayDate", "nextStatementDate", "nextLastPayDate",
                              "relationType", "relatedCardNumber", "relatedCardProductName"
                            ],
                            "properties": {
                              "cardNumber": { "type": "string" },
                              "cardNumberLast4": { "type": "string" },
                              "productName": { "type": "string" },
                              "statementWeek": { "type": "number", "enum": [1, 2, 3, 4] },
                              "statementDay": { "type": "number", "description": "Day of the month." },
                              "statementDate": { "$ref": "#/components/schemas/IssuedDate" },
                              "lastPayDate": { "$ref": "#/components/schemas/IssuedDate" },
                              "nextStatementDate": { "$ref": "#/components/schemas/Date" },
                              "nextLastPayDate": { "$ref": "#/components/schemas/Date" },
                              "relationType": { "type": "string", "enum": ["", "M", "C"] },
                              "relatedCardNumber": { "type": "string" },
                              "relatedCardProductName": { "type": "string" }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": { "$ref": "#/components/responses/InvalidArguments" },
            "401": { "$ref": "#/components/responses/GatewayUnauthorized" },
            "404": {
              "description": "Card not found: FB_IVR_CHANNEL_121, WARNING.",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/ErrorEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "result": {
                            "type": "object",
                            "properties": {
                              "returnCode": { "type": "string", "enum": ["FB_IVR_CHANNEL_121"] },
                              "code": { "type": "string", "enum": ["FB_IVR_CHANNEL_121"] },
                              "type": { "type": "string", "enum": ["WARNING"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "500": { "$ref": "#/components/responses/TechnicalError" }
          }
        }
      },
      "/voice/v1/statement.week.decide": {
        "post": {
          "operationId": "statement.week.decide",
          "description": "Preview only; does not change the card. Send the current statementDay from statement.week.get. Calling for the current week returns an error. Successful data.responseCode is 0. Dates describe the first statement and due date under the requested week.",
          "x-business-success": {
            "path": "result.returnCode",
            "operand": "1"
          },
          "requestBody": { "$ref": "#/components/requestBodies/WeekRequest" },
          "responses": {
            "200": {
              "description": "Success requires result.returnCode \"1\" and data.responseCode 0.",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/SuccessEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "data": {
                            "type": "object",
                            "required": [
                              "statementDate", "statementDueDate", "statementDay",
                              "responseCode", "responseMessage"
                            ],
                            "properties": {
                              "statementDate": { "$ref": "#/components/schemas/Date" },
                              "statementDueDate": { "$ref": "#/components/schemas/Date" },
                              "statementDay": { "type": "number" },
                              "responseCode": { "type": "number", "enum": [0] },
                              "responseMessage": { "type": "string" }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": { "$ref": "#/components/responses/InvalidArguments" },
            "401": { "$ref": "#/components/responses/GatewayUnauthorized" },
            "500": { "$ref": "#/components/responses/TechnicalError" }
          }
        }
      },
      "/voice/v1/statement.week.change": {
        "post": {
          "operationId": "statement.week.change",
          "description": "Changes the card only after the caller agrees to the preview dates. statementDay is mandatory even though the backend recalculates it; send the current day. Success also requires data.exitState \"OK\" and data.responseCode 0. Response statementWeek and statementDay are strings. Dates to report come from the preview, not this response.",
          "x-business-success": {
            "path": "result.returnCode",
            "operand": "1"
          },
          "requestBody": { "$ref": "#/components/requestBodies/WeekRequest" },
          "responses": {
            "200": {
              "description": "Success requires result.returnCode \"1\", data.exitState \"OK\" and data.responseCode 0.",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/SuccessEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "data": {
                            "type": "object",
                            "required": [
                              "responseCode", "responseMessage", "statementWeek",
                              "statementDay", "exitState"
                            ],
                            "properties": {
                              "responseCode": { "type": "number", "enum": [0] },
                              "responseMessage": { "type": "string" },
                              "statementWeek": { "type": "string" },
                              "statementDay": { "type": "string" },
                              "exitState": { "type": "string", "enum": ["OK"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": { "$ref": "#/components/responses/InvalidArguments" },
            "401": { "$ref": "#/components/responses/GatewayUnauthorized" },
            "500": { "$ref": "#/components/responses/TechnicalError" }
          }
        }
      },
      "/voice/v1/contact.email.get": {
        "post": {
          "operationId": "contact.email.get",
          "description": "Called with customerNo and intAddressInfoType. The requested information type does not change the test answer, but the field remains mandatory because an empty value explicitly returns 400. ibanEmail is the registered address; it and ttsEmail may be empty. The iban prefix does not refer to an IBAN.",
          "x-business-success": {
            "path": "result.returnCode",
            "operand": "1"
          },
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "allOf": [
                    { "$ref": "#/components/schemas/RequestEnvelope" },
                    {
                      "type": "object",
                      "properties": {
                        "data": {
                          "type": "object",
                          "required": ["customerNo", "intAddressInfoType"],
                          "properties": {
                            "customerNo": { "$ref": "#/components/schemas/CustomerNo" },
                            "intAddressInfoType": {
                              "type": "string",
                              "enum": ["E", "P", "B"],
                              "description": "E: email; P: phone; B: both."
                            }
                          }
                        }
                      }
                    }
                  ]
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Success: result.returnCode equals \"1\".",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/SuccessEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "data": {
                            "type": "object",
                            "required": [
                              "communicationType", "ibanCountryCode", "ibanAreaCode",
                              "ibanPhoneNum", "ibanEmail", "ttsEmail", "commGramType", "exitState"
                            ],
                            "properties": {
                              "communicationType": { "type": "string" },
                              "ibanCountryCode": { "type": "string" },
                              "ibanAreaCode": { "type": "string" },
                              "ibanPhoneNum": { "type": "string" },
                              "ibanEmail": { "type": "string" },
                              "ttsEmail": { "type": "string" },
                              "commGramType": { "type": "string" },
                              "exitState": { "type": "string" }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": { "$ref": "#/components/responses/InvalidArguments" },
            "401": { "$ref": "#/components/responses/GatewayUnauthorized" },
            "500": { "$ref": "#/components/responses/TechnicalError" }
          }
        }
      },
      "/voice/v1/statement.pdf.send": {
        "post": {
          "operationId": "statement.pdf.send",
          "description": "Sends the PDF to emailAddress supplied in the request. Send the issued statementDate from cards.balance. The backend does not compare emailAddress with the registered address. All declared service inputs remain mandatory even though test fixtures select an answer by customerNo alone. Successful data.exitState is DONE.",
          "x-business-success": {
            "path": "result.returnCode",
            "operand": "1"
          },
          "requestBody": {
            "required": true,
            "content": {
              "application/json": {
                "schema": {
                  "allOf": [
                    { "$ref": "#/components/schemas/RequestEnvelope" },
                    {
                      "type": "object",
                      "properties": {
                        "data": {
                          "type": "object",
                          "required": [
                            "customerNo", "cardNumber", "currencyType",
                            "statementDate", "emailAddress"
                          ],
                          "properties": {
                            "customerNo": { "$ref": "#/components/schemas/CustomerNo" },
                            "cardNumber": { "type": "string", "minLength": 1 },
                            "currencyType": { "type": "string", "enum": ["TL", "USD", "EUR", "GBP"] },
                            "statementDate": { "$ref": "#/components/schemas/Date" },
                            "emailAddress": { "type": "string", "minLength": 1 }
                          }
                        }
                      }
                    }
                  ]
                }
              }
            }
          },
          "responses": {
            "200": {
              "description": "Success requires result.returnCode \"1\"; successful data.exitState is \"DONE\".",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/SuccessEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "data": {
                            "type": "object",
                            "required": ["exitState"],
                            "properties": {
                              "exitState": { "type": "string", "enum": ["DONE"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": { "$ref": "#/components/responses/InvalidArguments" },
            "401": { "$ref": "#/components/responses/GatewayUnauthorized" },
            "404": {
              "description": "No statement PDF: FB_IVR_CHANNEL_107, WARNING. Message: Pdf dokümanı bulunamadı.",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      { "$ref": "#/components/schemas/ErrorEnvelope" },
                      {
                        "type": "object",
                        "properties": {
                          "result": {
                            "type": "object",
                            "properties": {
                              "returnCode": { "type": "string", "enum": ["FB_IVR_CHANNEL_107"] },
                              "code": { "type": "string", "enum": ["FB_IVR_CHANNEL_107"] },
                              "type": { "type": "string", "enum": ["WARNING"] }
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "500": { "$ref": "#/components/responses/TechnicalError" }
          }
        }
      }
    },
    "components": {
      "schemas": {
        "CustomerNo": {
          "oneOf": [
            { "type": "string", "minLength": 1 },
            { "type": "number" }
          ],
          "description": "Customer number; string and number forms are accepted in test."
        },
        "Date": {
          "type": "string",
          "pattern": "^[0-9]{2}\\.[0-9]{2}\\.[0-9]{4}$",
          "description": "dd.MM.yyyy."
        },
        "IssuedDate": {
          "type": "string",
          "pattern": "^([0-9]{2}\\.[0-9]{2}\\.[0-9]{4})?$",
          "description": "dd.MM.yyyy, or an empty string when no statement has been issued."
        },
        "DebtStatus": {
          "type": "string",
          "enum": ["HAS_DEBT", "NO_DEBT"]
        },
        "RequestEnvelope": {
          "type": "object",
          "required": ["data"],
          "properties": {
            "data": { "type": "object" },
            "call": {
              "type": "object",
              "description": "Optional incidental metadata; the test environment ignores this object and its nested fields.",
              "properties": {
                "ani": { "type": "string" },
                "lang": { "type": "string" }
              }
            }
          }
        },
        "CardRequest": {
          "allOf": [
            { "$ref": "#/components/schemas/RequestEnvelope" },
            {
              "type": "object",
              "properties": {
                "data": {
                  "type": "object",
                  "required": ["cardNumber"],
                  "properties": {
                    "cardNumber": {
                      "type": "string",
                      "minLength": 1,
                      "description": "Exactly as returned by cards.list."
                    }
                  }
                }
              }
            }
          ]
        },
        "WeekRequest": {
          "allOf": [
            { "$ref": "#/components/schemas/RequestEnvelope" },
            {
              "type": "object",
              "properties": {
                "data": {
                  "type": "object",
                  "required": ["cardNumber", "newStatementWeek", "statementDay"],
                  "properties": {
                    "cardNumber": { "type": "string", "minLength": 1 },
                    "newStatementWeek": {
                      "oneOf": [
                        { "type": "number", "enum": [1, 2, 3, 4] },
                        { "type": "string", "enum": ["1", "2", "3", "4"] }
                      ]
                    },
                    "statementDay": {
                      "type": "number",
                      "description": "Current statementDay from statement.week.get."
                    }
                  }
                }
              }
            }
          ]
        },
        "Card": {
          "type": "object",
          "required": ["cardNumber", "cardNumberLast4", "productName", "status", "isMainCard"],
          "properties": {
            "cardNumber": { "type": "string" },
            "cardNumberLast4": { "type": "string" },
            "productName": { "type": "string" },
            "status": { "type": "string", "enum": ["A"] },
            "isMainCard": { "type": "boolean" }
          }
        },
        "CurrencyBlock": {
          "description": "May be exactly empty. Ordinary populated blocks have all declared fields. Existence is optional in the containing balance model.",
          "oneOf": [
            { "type": "object", "enum": [{}] },
            { "$ref": "#/components/schemas/Debt" }
          ]
        },
        "Debt": {
          "type": "object",
          "required": [
            "statementPaymentStatus", "transferAmount", "statementDebt",
            "minPayment", "remainingDebt", "remainingMinPayment",
            "currentPeriodExpense", "totalDebt", "totalDebtPaymentStatus",
            "remainAutomaticPaymentAmount"
          ],
          "properties": {
            "statementPaymentStatus": { "$ref": "#/components/schemas/DebtStatus" },
            "transferAmount": { "type": "number" },
            "statementDebt": { "type": "number" },
            "minPayment": { "type": "number" },
            "remainingDebt": { "type": "number" },
            "remainingMinPayment": { "type": "number" },
            "currentPeriodExpense": { "type": "number" },
            "totalDebt": {
              "type": "number",
              "description": "Includes spending after the statement. May be negative, meaning a credit balance; status is then NO_DEBT."
            },
            "totalDebtPaymentStatus": { "$ref": "#/components/schemas/DebtStatus" },
            "remainAutomaticPaymentAmount": {
              "type": "number",
              "description": "Meaningful only when the card's automaticPaymentFlag is Y."
            }
          }
        },
        "SuccessEnvelope": {
          "type": "object",
          "required": ["data", "result"],
          "properties": {
            "data": { "type": "object" },
            "result": { "$ref": "#/components/schemas/SuccessResult" }
          }
        },
        "SuccessResult": {
          "type": "object",
          "required": ["guid", "returnCode", "messageText", "code", "message", "type", "details"],
          "properties": {
            "guid": { "type": "string", "description": "Bank trace identifier." },
            "returnCode": { "type": "string", "enum": ["1"] },
            "messageText": { "type": "string" },
            "code": { "type": "string", "enum": ["1"] },
            "message": { "type": "string" },
            "type": { "type": "string", "nullable": true, "enum": [null] },
            "details": {
              "type": "object",
              "required": ["guid", "rootCause", "errorOrigin"],
              "properties": {
                "guid": { "type": "string" },
                "rootCause": { "type": "string", "nullable": true, "enum": [null] },
                "errorOrigin": { "type": "string", "nullable": true, "enum": [null] }
              }
            }
          },
          "description": "returnCode and code are equal; messageText and message are equal. The section 3 successful envelope has null diagnostic values."
        },
        "ErrorEnvelope": {
          "type": "object",
          "required": ["result"],
          "additionalProperties": false,
          "properties": {
            "result": {
              "type": "object",
              "required": ["guid", "returnCode", "messageText", "code", "message", "type", "details"],
